pan(){const av=Math.round(team.reduce((a,m)=>a+m.p,0)/team.length),op=[...hall,...demoH].filter(h=>(h.s||0)<2).length,k=(l,v)=>`<div class="card"><span class="mut">${l}</span><h2 style="margin:4px 0">${v}</h2></div>`;return`<div class="grid g3">${k(x('Trabajadores','Workers'),team.length)}${k(x('Cumplimiento promedio','Avg. compliance'),av+'%')}${k(x('Hallazgos abiertos','Open findings'),op)}</div><div class="card" style="margin-top:16px">${team.map(m=>`<div class="row"><div style="flex:1"><b>${esc(m.n)}</b> <span class="tag">${P(H[m.a].n)}</span> <span class="tag">${LN[m.l]}</span><div class="bar" style="margin-top:6px"><i style="width:${m.p}%;background:${m.p<60?'var(--red)':'var(--teal)'}"></i></div></div><b>${m.p}%</b>${m.p<60?`<button class="g" onclick="toast('✓ ${LN[m.l]}')">${x('Recordar','Remind')}</button>`:''}</div>`).join('')}</div>`},
rev(){const N=[x('Recibido','Received'),x('En revisión','In review'),x('Cerrado','Closed')],a=[...hall,...demoH];return`<div class="card">${a.map((h,i)=>`<div class="row"><div><b>${esc(h.a)}</b><br><span class="mut">${esc(h.d)}</span></div><span><span class="tag ${(h.s||0)==2?'ok':'go'}">${N[h.s||0]}</span> ${(h.s||0)<2?`<button class="g" onclick="adv(${i})">→</button>`:''}</span></div>`).join('')}</div>`},
