async function adv(i){const h=[...hall,...demoH][i];if(!h)return;h.s=Math.min(2,(h.s||0)+1);render();if(dbh&&h.id){try{await fetch('/api/data/findings/'+encodeURIComponent(h.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:h.s})})}catch(e){}}}
function addW(){const n=$('#wn').value.trim();if(!n)return;team.push({n,a:$('#wa').value,l:$('#wl').value,p:0,u:n.toLowerCase().replace(/[^a-z]/g,''),k:String(Math.floor(1000+Math.random()*9000))});render()}

function md(t){const e=z=>z.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),n=z=>e(z).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>');let h='',tb=[],ls=0;const ft=()=>{if(tb.length){h+='<div style="overflow-x:auto"><table class="tb">'+tb.map(r=>'<tr>'+r.map(c=>'<td>'+n(c)+'</td>').join('')+'</tr>').join('')+'</table></div>';tb=[]}},fl=()=>{if(ls){h+='</ul>';ls=0}};
(t||'').split('\n').forEach(l=>{const z=l.trim();if(!z){ft();fl();return}if(z[0]=='|'){fl();tb.push(z.replace(/^\||\|$/g,'').split('|').map(c=>c.trim()));return}ft();if(/^[-*•] /.test(z)){if(!ls){h+='<ul class="l">';ls=1}h+='<li>'+n(z.slice(2))+'</li>';return}fl();h+='<p>'+n(z)+'</p>'});ft();fl();return h}
function build(){const ids=new Set(SEED.map(d=>d.id));Object.values(MM).forEach(m=>m&&m.id&&ids.add(m.id));DOCS=[...ids].map(id=>{const sd=SEED.find(d=>d.id==id)||{secs:[]},m=MM['d'+id]||{};if(m.del)return null;const b={id,title:sd.title,law:sd.law,cat:sd.cat,area:sd.area||'all',g:sd.g,...m},sm={};sd.secs.forEach(z=>sm[z.id]=z);Object.values(SS).filter(z=>z.doc==id).forEach(z=>sm[z.id]=z);const o=[...(m.order||sd.secs.map(z=>z.id))];Object.keys(sm).forEach(k=>{if(!o.includes(k))o.push(k)});b.secs=o.map(k=>sm[k]).filter(z=>z&&!z.del);return b}).filter(Boolean)}
let dbReady=null;
function initDB(){if(!dbReady)dbReady=(async()=>{try{const res=await fetch('/api/data/bootstrap');if(!res.ok)return;const json=await res.json();if(!json.configured){dbh=null;if(json.schemaMissing)console.warn(json.reason);return}dbh=true;const d=json.data||{};if(d.docs){Object.keys(MM).forEach(k=>delete MM[k]);Object.assign(MM,d.docs)}if(d.secs){Object.keys(SS).forEach(k=>delete SS[k]);Object.assign(SS,d.secs)}if(d.ui){Object.keys(d.ui).forEach(lg=>Object.assign(TR[lg]||(TR[lg]={}),d.ui[lg]))}if(d.qz)Object.assign(QZD,d.qz);if(d.qzt)Object.assign(QZT,d.qzt);if(d.team){Object.keys(TD).forEach(k=>delete TD[k]);Object.assign(TD,d.team);mergeTeam()}if(d.prog){Object.keys(PR).forEach(k=>delete PR[k]);Object.assign(PR,d.prog)}if(Array.isArray(d.hall)){hall.length=0;d.hall.forEach(item=>hall.push(item))}build();if(user)syncFromRemoteProg();if(!$('#m').classList.contains('on')){if($('#app').style.display=='grid')render();else drawLogin()}}catch(e){dbh=null}})();return dbReady}
async function put(c,k,d,q){if(q&&!dbh)return;if(!dbh){toast(x('Sin base de datos: configura Supabase en .env.local','No database: configure Supabase in .env.local'));return}try{const res=await fetch('/api/data/'+encodeURIComponent(c)+'/'+encodeURIComponent(k),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});if(!res.ok){const err=await res.json().catch(()=>({}));if(!q)toast(err.error||x('No se pudo guardar en Supabase','Could not save to Supabase'))}}catch(e){if(!q)toast(x('Error de conexión con la base de datos','Database connection error'))}}
const dm=id=>DOCS.find(z=>z.id==id);
function saveMeta0(d){const m={...(MM['d'+d.id]||{}),id:d.id,title:d.title,law:d.law,cat:d.cat,area:d.area,order:d.secs.map(z=>z.id)};MM['d'+d.id]=m;build();return put('docs','d'+d.id,m)}
Object.assign(V,{dx(){return`<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><p class="mut" style="margin:0">${x('Edita, agrega, traduce o quita documentos. Cada traducción se guarda una sola vez en Supabase para todos.','Edit, add, translate or remove documents. Each translation is saved once in Supabase for everyone.')}</p><span><button onclick="newDoc()">+ ${x('Nuevo documento','New document')}</button></span></div><div class="card" style="margin-top:16px">${DOCS.length?DOCS.map(d=>`<div class="row"><div style="min-width:0"><b>${esc(docTitle(d))}</b><br><span class="tag">${esc(tx(d.law||'—'))}</span> <span class="tag go">${x('Documento','Document')}</span> <span class="mut">${d.secs.length} ${x('secciones','sections')}</span><div style="margin-top:6px;display:flex;gap:4px;flex-wrap:wrap">${flTags(d.id)} ${QES(d.id).length?'':`<span class="tag go">${x('Sin preguntas: oculto para trabajadores','No questions: hidden from workers')}</span>`}</div></div><span style="white-space:nowrap"><button class="g" onclick="reader({id:${d.id}},1)">${t('open')}</button> <button class="g" onclick="fmOpen(${d.id})" title="${x('Archivos por idioma','Files by language')}">📁</button> <button onclick="edDoc(${d.id})">✎</button> <button class="g" onclick="askDelDoc(${d.id})">✕</button></span></div>`).join(''):`<p class="mut" style="margin:0">${x('Aún no hay documentos cargados. Agrega uno nuevo o súbelo en "Subir material".','No documents have been uploaded yet. Add a new one or upload it in "Upload material".')}</p>`}</div>`}});
function newDoc(ti,law,area){const id=1000+Math.floor(Math.random()*9e5),sid='s'+id+'_0';SS[sid]={id:sid,doc:id,h:x('Sección 1','Section 1'),t:''};MM['d'+id]={id,title:ti||x('Nuevo documento','New document'),law:law||'',cat:'doc',area:area||'all',nw:1,order:[sid]};build();put('docs','d'+id,MM['d'+id]).then(()=>put('secs',sid,SS[sid]));edDoc(id)}
function askDelDoc(id){const d=dm(id);if(!d)return;const fl=Object.keys(FLG[id]||{}),nq=QES(id).length;M(`<h3>⚠️ ${x('¿Eliminar este documento?','Delete this document?')}</h3><p><b>${esc(docTitle(d))}</b></p><p>${x('Se borrarán de forma permanente:','The following will be permanently deleted:')}</p><ul class="l"><li>${fl.length?x('Los archivos en','The files in')+' '+fl.length+' '+x('idiomas','languages')+' ('+fl.map(l=>l.toUpperCase()).join(', ')+')':x('El documento (no tiene archivos)','The document (it has no files)')}</li><li>${nq} ${x('preguntas de evaluación y sus traducciones','test questions and their translations')}</li></ul><p><b>${x('Esta acción no se puede deshacer.','This action cannot be undone.')}</b> ${x('Los trabajadores dejarán de ver el documento.','Workers will no longer see the document.')}</p><label style="display:flex;gap:8px;align-items:center;margin:10px 0"><input type="checkbox" id="delok" style="width:auto" onchange="$('#delbtn').disabled=!this.checked"> ${x('Entiendo que se borrará definitivamente','I understand it will be permanently deleted')}</label><div style="display:flex;gap:8px"><button id="delbtn" disabled style="background:var(--red)" onclick="delDoc(${id})">${x('Sí, eliminar','Yes, delete')}</button><button class="g" onclick="X()">${x('Cancelar','Cancel')}</button></div>`)}
async function delDoc(id){const b=$('#delbtn');if(b){b.disabled=true;b.textContent=x('Eliminando…','Deleting…')}try{const r=await fetch('/api/docs/'+id,{method:'DELETE'});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'HTTP '+r.status);delete MM['d'+id];Object.keys(SS).forEach(k=>{if(SS[k].doc==id)delete SS[k]});delete QZD['q'+id];Object.keys(QZT).forEach(k=>{if(k.startsWith(id+'_'))delete QZT[k]});delete FLG[id];build();X();toast('✓ '+x('Documento eliminado','Document deleted'))}catch(e){toast(x('No se pudo eliminar: ','Could not delete: ')+e.message);if(b){b.disabled=false;b.textContent=x('Sí, eliminar','Yes, delete')}}}

