V.dx0=V.dx;V.dx=function(){return this.dx0()+`<div class="card" style="margin-top:16px"><b>${L5(NS.ev)}</b>${allQ().map(z=>`<div class="row"><div style="min-width:0"><b>${esc(T4(z.t))}</b><br><span class="mut">${QS(z.id).length} ${L5(NS.qn)}</span></div><button onclick="edQz(${z.id})">✎</button></div>`).join('')}</div>`};
function edQz(id){const qs=QS(id);M(`<h3>${L5(NS.ev)}</h3><p class="mut">${esc(T4(allQ().find(z=>z.id==id).t))}</p><p class="mut">${qs.length}/5 · ≥80%</p>${qs.map((q,k)=>`<div class="row"><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${k+1}. ${esc(q.q)}</span><span style="white-space:nowrap"><button class="g" onclick="edQ(${id},${k})">✎</button> <button class="g" onclick="delQ(${id},${k})">✕</button></span></div>`).join('')}<p></p><div style="display:flex;gap:8px"><button class="t" onclick="edQ(${id},${qs.length})">+ ${L5(NS.aq)}</button><button class="g" onclick="X()">${t('cl')}</button></div>`)}
function edQ(id,k){const q=QS(id)[k]||{q:'',o:['','',''],w:''};M(`<h3>${L5(NS.qq)} ${k+1}</h3><label>${L5(NS.qq)}</label><input id="q0" value="${esc(q.q)}"><label>✔ ${L5(NS.qc)}</label><input id="q1" value="${esc(q.o[q.c||0]||'')}"><label>✖ ${L5(NS.qw)} 1</label><input id="q2" value="${esc(q.o[(q.c||0)==0?1:0]||'')}"><label>✖ ${L5(NS.qw)} 2</label><input id="q3" value="${esc(q.o[(q.c||0)==2?1:2]||'')}"><label>${L5(NS.qe)}</label><textarea id="q4" rows="3">${esc(q.w||'')}</textarea><p></p><div style="display:flex;gap:8px"><button onclick="saveQ(${id},${k})">${x('Guardar','Save')}</button><button class="g" onclick="edQz(${id})">${x('Volver','Back')}</button></div>`)}
function qzSave(id,qs){QZD['q'+id]={id,qs};put('qz','q'+id,{id,qs});edQz(id)}
function saveQ(id,k){const v=n=>$('#q'+n).value.trim();if(!v(0)||!v(1)||!v(2))return;const qs=[...QS(id)];qs[k]={q:v(0),o:[v(1),v(2),v(3)].filter(Boolean),c:0,w:v(4)};qzSave(id,qs)}
function delQ(id,k){const qs=[...QS(id)];qs.splice(k,1);qzSave(id,qs)}

const IMG={m:"assets/img/img_01.jpg",o:"assets/img/img_02.jpg"};
