const CAMP=[{id:'m',img:'m',ico:['✂️','🔥','🧴','🪨','🦠'],t:'Tus manos también trabajan',sub:'Cuidarlas es parte del trabajo, es parte de tu seguridad.',lema:'Manos sanas, trabajo seguro',foot:'Tus manos no son solo herramientas… son tu futuro.',r:[['Cortes y heridas','por herramientas, materiales o superficies filosas.'],['Quemaduras','por contacto con superficies calientes, químicos o electricidad.'],['Irritaciones y dermatitis','por el contacto con sustancias químicas o agentes irritantes.'],['Golpes y aplastamientos','por maquinaria, objetos pesados o apriete de piezas.'],['Infecciones','por contacto con superficies contaminadas o falta de higiene.']],k:[['Usa los equipos de protección','Guantes adecuados para cada tarea. No los improvises.'],['Mantén una buena higiene','Lava tus manos con agua y jabón, especialmente al terminar la jornada o después de manipular químicos.'],['Revisa tus herramientas','Asegúrate de que estén en buen estado y usa las herramientas correctas para cada trabajo.'],['Cuida tu piel','Hidrata tus manos y evita el contacto directo con sustancias agresivas.'],['Mantén la atención','Evita distracciones y respeta los procedimientos de seguridad.']]},
{id:'u',img:'u',ico:['☀️','⏳','🩺','👁️','⛰️'],t:'Protege tu piel',sub:'El sol también es un riesgo laboral.',lema:'Cuida hoy tu piel, para un mejor mañana',foot:'Prevenir el riesgo UV también es trabajar seguro.',rh:'¿Por qué es importante?',intro:'La exposición prolongada a la radiación UV en el trabajo puede provocar:',r:[['Quemaduras solares','Agudas y dolorosas.'],['Envejecimiento prematuro de la piel','Arrugas, manchas y pérdida de elasticidad.'],['Cáncer de piel','El más grave y prevenible.'],['Daño en los ojos','Conjuntivitis y cataratas.'],['Mayor exposición','Trabajo al aire libre, altas altitudes, horario de mayor radiación (10:00 a 16:00 h) y superficies que reflejan la luz (arena, agua, nieve, metal).']],k:[['Usa protector solar de amplio espectro','FPS 50+ y reaplícalo cada 2 a 3 horas.'],['Usa ropa de manga larga','Ligera y de colores claros.'],['Utiliza sombrero o jockey','Que proteja cara, cuello y orejas.'],['Usa lentes de sol con filtro UV','Cuida tus ojos de la radiación.'],['Hidrátate constantemente','Toma agua durante toda la jornada.']],prt:'Protocolo UV',pr:[['P','Planificación','Identifica la exposición y define medidas preventivas.'],['R','Reconocimiento','Evalúa las condiciones y niveles de radiación UV.'],['E','Ejecución','Aplica controles (EPP, capacitación, organización del trabajo).'],['X','Seguimiento','Verifica la efectividad de las medidas y realiza mejoras continuas.']]},
{id:'e',img:'e',ico:['📦','🧍','🔁','⏱️','🛌'],t:'Protege tu espalda',sub:'Tu espalda también trabaja, cuídala hoy.',lema:'Prevenir es cuidar tu salud y tu futuro',foot:'¡Tu espalda no tiene reemplazo!',rh:'Factores que aumentan el riesgo',intro:'Los TMERT son lesiones o dolores en músculos, tendones, articulaciones y espalda, causados o agravados por el trabajo. Zonas más afectadas: espalda lumbar, hombros, cuello, muñecas y manos. Síntomas: dolor, rigidez, fatiga y menor movilidad.',r:[['Cargas pesadas o mal manipuladas','Levantar o mover peso de forma incorrecta carga la espalda.'],['Posturas forzadas o repetitivas','Mantener posturas difíciles o repetirlas durante la jornada.'],['Movimientos repetitivos','Repetir el mismo movimiento muchas veces sin variar.'],['Permanecer mucho tiempo en la misma posición','De pie o sentado sin cambiar de postura.'],['Falta de pausas y descanso','Sin pausas el cuerpo no se recupera.']],k:[['Levanta con las piernas, no con la espalda','Mantén la carga cerca de tu cuerpo.'],['Ajusta tu puesto de trabajo','La silla, pantalla y herramientas deben estar a la altura correcta.'],['Haz pausas activas','Estira y cambia de postura cada cierto tiempo.'],['Usa ayudas mecánicas','Carros, elevadores y equipos de apoyo.'],['Trabaja en equipo','Maneja cargas pesadas entre dos o más personas.'],['Mantén el orden y la limpieza','Evita tropiezos y esfuerzos innecesarios.']],prt:'Protocolo TMERT',pr:[['T','Identificación','Reconoce tareas, posturas y factores de riesgo.'],['M','Evaluación','Analiza el nivel de riesgo y la afectación de los trabajadores.'],['E','Medidas de control','Implementa mejoras en el puesto, equipo y organización.'],['R','Seguimiento','Verifica la efectividad de las medidas y realiza ajustes.']]},
{id:'a',img:'a',ico:['👂','🔔','🧠'],t:'Protege tus oídos',sub:'Tu audición también es parte de tu seguridad laboral.',lema:'Hoy previenes el ruido, mañana mantienes tu futuro',foot:'¡La prevención es tarea de todos!',rh:'¿Cuáles son los riesgos?',intro:'En muchos lugares de trabajo, el ruido puede superar los límites seguros y causar daños en la audición. Este riesgo es real y prevenible. ¡El daño no siempre se nota de inmediato!',r:[['Pérdida auditiva','Es irreversible.'],['Zumbidos en los oídos','Acúfenos.'],['Dificultad para concentrarse y mayor estrés','El ruido constante afecta la atención y el ánimo.']],k:[['Usa siempre tus protectores auditivos','Son tu primera barrera contra el ruido.'],['Asegúrate de que estén en buen estado','Y que sean del tipo adecuado a tu tarea.'],['Respeta las zonas de alto ruido','Y las señalizaciones.'],['Mantén los equipos y la maquinaria en buen estado','Un equipo bien mantenido hace menos ruido.'],['Participa en las capacitaciones de seguridad','Pequeños gestos, grandes diferencias.']],prt:'Protocolo PREXOR',pr:[['P','Prevención','Identifica y elimina o reduce los riesgos.'],['R','Reconocimiento','Evalúa los peligros y la exposición (ruido, maquinaria, procesos).'],['E','Evaluación','Analiza los resultados y determina medidas de control.'],['X','Control','Implementa medidas técnicas, administrativas y EPP.'],['O','Organización','Define responsabilidades, capacita y comunica.'],['R','Revisión','Verifica la eficacia de las medidas y mejora continuamente.']]},
{id:'o',img:'o',ico:['🌫️','🧪','⚡','💥','🦠'],t:'Cuida tus ojos',sub:'Los ojos son irreemplazables. Protégelos hoy, para seguir viendo tu futuro.',lema:'Tus ojos trabajan contigo',foot:'No arriesgues lo que te permite ver el mundo.',r:[['Partículas y polvo','Virutas, escombros, polvo fino y otros residuos.'],['Sustancias químicas','Productos de limpieza, pinturas, solventes y ácidos.'],['Radiación y luz intensa','Arco eléctrico, soldadura, rayos UV e infrarrojos.'],['Proyecciones y golpes','Herramientas, materiales y objetos en movimiento.'],['Agentes biológicos','Bacterias, virus y microorganismos del entorno.']],k:[['Usa protección ocular adecuada','Elige el equipo correcto según el tipo de riesgo (lentes de seguridad, caretas, gafas de soldar, etc.).'],['Evita tocarte los ojos','Tus manos pueden llevar suciedad, químicos o microorganismos.'],['Mantén la higiene','Limpia y cuida tus lentes de seguridad. Reemplázalos si están dañados o con rayaduras.'],['Identifica los riesgos','Observa tu entorno y sigue los procedimientos de seguridad de cada tarea.'],['Hazte chequeos visuales','Revisa tu visión periódicamente y reporta cualquier molestia o alteración.']]}];
