let CV=null;
const cm=id=>cmp[id]||(cmp[id]={r:[0,0,0,0,0],k:0,c:[0,0,0,0,0],d:0});
const cpc=id=>{const o=cm(id),c=CAMP.find(z=>z.id==id);return Math.round((o.r.filter(Boolean).length/c.r.length+o.k/c.k.length+(o.d?1:0))/3*100)};
V.cp=function(){if(CV)return cView();return`<p class="mut">${x('Láminas interactivas de prevención: recorre los riesgos, las claves y firma tu compromiso.','Interactive prevention sheets: explore the risks, the 5 keys and sign your commitment.')}</p><div class="grid g3">${campVis().map(c=>`<div class="card" style="padding:0;overflow:hidden"><div style="height:130px;background:#0B0B0D url(${IMG[c.img]}) right center/cover"></div><div style="padding:18px"><b>${tx(c.t)}</b><div class="bar" style="margin:10px 0 6px"><i style="width:${cpc(c.id)}%"></i></div><p class="mut" style="margin:0 0 12px">${cpc(c.id)}%</p><button onclick="CV={id:'${c.id}',tab:'r'};render()">${cpc(c.id)?x('Continuar','Continue'):x('Abrir lámina','Open sheet')}</button></div></div>`).join('')}${PRX.map(a=>`<div class="card" style="border-style:dashed;text-align:center"><div style="font-size:34px">${a[0]}</div><b>${tx(a[1])}</b><p class="mut">${x('Próximamente','Coming soon')}</p></div>`).join('')}</div>`};
function cView(){const c=CAMP.find(z=>z.id==CV.id),o=cm(c.id),tb=[['r',x('Riesgos','Risks')],['k',x('Claves','Keys')],...(c.pr?[['p',x('Protocolo','Protocol')]]:[]),['c',x('Mi compromiso','My commitment')]];let b='';
if(CV.tab=='r')b=`<h3>${c.rh?tx(c.rh):x('¿Qué riesgos enfrentas?','What risks do you face?')}</h3>${c.intro?`<p class="mut">${tx(c.intro)}</p>`:''}${c.r.map((z,i)=>`<button class="rk ${o.r[i]?'on':''}" onclick="cmR('${c.id}',${i})"><i>${c.ico[i]}</i><span><b>${tx(z[0])}</b><span class="d">${tx(z[1])}</span></span></button>`).join('')}<p class="mut">${o.r.filter(Boolean).length}/${c.r.length}</p>`;
else if(CV.tab=='k'){const s=Math.min(CV.s??o.k,c.k.length-1),z=c.k[s];b=`<div style="text-align:center"><div class="bn">${s+1}</div><h3>${tx(z[0])}</h3><p class="mut">${tx(z[1])}</p><div class="dots">${c.k.map((q,i)=>`<i class="${i<o.k?'on':''}"></i>`).join('')}</div><button class="g" ${s?'':'disabled'} onclick="CV.s=${s-1};render()">←</button> <button onclick="cmK('${c.id}',${s})">${o.k>s?x('Siguiente','Next'):x('Entendido','Got it')} →</button></div>`}
else if(CV.tab=='p')b=`<h3>${tx(c.prt)}</h3>${c.pr.map(z=>`<div class="rk on" style="cursor:default"><i style="background:#FFC800;color:#111;font-weight:800;font-size:24px">${z[0]}</i><span><b>${tx(z[1])}</b><span class="d">${tx(z[2])}</span></span></div>`).join('')}`;else b=`<h3>${x('Me comprometo a:','I commit to:')}</h3>${c.k.map((z,i)=>`<label class="cl"><input type="checkbox" ${o.c[i]?'checked':''} onchange="cm('${c.id}').c[${i}]=this.checked?1:0;saveLS();render()">${tx(z[0])}</label>`).join('')}<p></p>${o.d?`<p><b>✅ ${x('Campaña completada','Campaign completed')}</b></p>`:`<button ${c.k.every((q,i)=>o.c[i])?'':'disabled'} onclick="cmD('${c.id}')">${x('Firmar compromiso','Sign commitment')}</button>`}`;
return`<button class="g" onclick="CV=null;render()">← ${x('Campañas','Campaigns')}</button><div class="ch" style="margin-top:12px;background-image:linear-gradient(90deg,#0B0B0D 38%,#0B0B0D00),url(${IMG[c.img]})"><span class="pill">${x('PREVENCIÓN DE RIESGOS','RISK PREVENTION')}</span><h2>${tx(c.t)}</h2><p style="margin:0;max-width:26em;opacity:.9">${tx(c.sub)}</p><p class="y" style="margin:8px 0 0;font-style:italic">${tx(c.lema)}</p></div><div class="lang">${tb.map(a=>`<button class="g ${CV.tab==a[0]?'on':''}" onclick="CV.tab='${a[0]}';CV.s=undefined;render()">${a[1]}</button>`).join('')}</div><div class="card">${b}</div>${c.docs?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px">${c.docs.map(id=>DOCS.find(d=>d.id==id)).filter(Boolean).map(d=>`<button class="g" onclick="reader({id:${d.id}},1)">📄 ${esc(docTitle(d))}</button>`).join('')}</div>`:''}<p class="mut" style="text-align:center;margin-top:16px">${tx(c.foot)}</p>`}
function cmR(id,i){const o=cm(id);o.r[i]=o.r[i]?0:1;saveLS();render()}
function cmK(id,s){const o=cm(id);if(o.k<=s)o.k=s+1;saveLS();if(s>=CAMP.find(z=>z.id==id).k.length-1){CV.tab='c';CV.s=undefined}else CV.s=s+1;render()}
function cmD(id){const o=cm(id);o.d=1;saveLS();render();toast('✓ +30')}
