const cargoArea=n=>{for(const g of CARGOS)for(const c of g[1])if(c[0]==n)return c[1];return ''};
const cargoSel=sel=>`<select id="pc" onchange="pcCh(this.value)"><option value="">—</option>${CARGOS.map(g=>`<optgroup label="${esc(tx(g[0]))}">${g[1].map(c=>`<option value="${esc(c[0])}" ${c[0]==sel?'selected':''}>${esc(tx(c[0]))}</option>`).join('')}</optgroup>`).join('')}</select>`;
