const allIds=()=>DOCS.map(d=>d.id);
function defAsg(a){if(a=='jef')return[...allIds(),...CAMP.map(c=>'c:'+c.id)];const ofi=a=='ofi',cs=ofi?['e','o','k','l']:['m','o','u','a','e','l','s','k'];return[...new Set([...docIdsFor(a),...cs.map(z=>'c:'+z)])]}
const ukey=()=>user.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,''),meRec=()=>team.find(m=>m.u==ukey());
const asgOf=m=>m.asg?m.asg.filter(k=>typeof k!='number'||DOCS.some(d=>d.id==k)):defAsg(m.a);
function asgSet(){if(role=='p')return null;const m=meRec();let a=m&&asgOf(m);if(!a&&prof.cargo)a=defAsg(cargoArea(prof.cargo)||prof.area);return a?new Set(a):null}
