function mergeTeam(){const su=new Set(TSEED.map(m=>m.u)),out=TSEED.map(m=>({...m,...(TD[m.u]||{})})).filter(m=>!m.del);Object.values(TD).forEach(m=>{if(!su.has(m.u)&&!m.del)out.push(m)});team.length=0;out.forEach(m=>team.push(m))}
