const MY={img:''};
function avatar(n,img,sz){return`<span class="av" style="width:${sz}px;height:${sz}px;font-size:${Math.round(sz*.42)}px">${img?`<img src="${img}" alt="">`:esc(((n||'?')[0]||'?').toUpperCase())}</span>`}
function resizeImg(file,cb){const im=new Image(),url=URL.createObjectURL(file);im.onload=()=>{const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d'),s=Math.min(im.width,im.height);g.drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,256,256);URL.revokeObjectURL(url);cb(c.toDataURL('image/jpeg',.78))};im.onerror=()=>toast(x('No se pudo leer la imagen','Could not read the image'));im.src=url}
function upPhoto(inp){const f=inp.files&&inp.files[0];if(!f)return;resizeImg(f,d=>{MY.img=d;try{localStorage.setItem(lsk()+'_av',d)}catch(e){}pushSnap();render();toast('✓')})}
function rmPhoto(){MY.img='';try{localStorage.removeItem(lsk()+'_av')}catch(e){}pushSnap();render()}
const photoCard=()=>{const A=asgSet();return`<div class="card" style="display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin-bottom:16px">${avatar(user,MY.img,96)}<div style="flex:1;min-width:200px"><b style="font-size:18px">${esc(user)}</b><p class="mut" style="margin:2px 0 10px">${x('Agrega una foto para que tu perfil sea único.','Add a photo to make your profile yours.')}${A?` · ${A.size} ${x('contenidos en tu plan','items in your plan')}`:''}</p><label class="fbtn">📷 ${x('Subir foto','Upload photo')}<input type="file" accept="image/*" hidden onchange="upPhoto(this)"></label> ${MY.img?`<button class="g" onclick="rmPhoto()">${x('Quitar','Remove')}</button>`:''}</div></div>`};
V.perf0=V.perf;V.perf=function(){return photoCard()+this.perf0()};
