const catalog=()=>{const a=[];DOCS.forEach(d=>a.push({k:d.id,t:docTitle(d),g:d.g||'Otros documentos',_doc:1}));CAMP.forEach(c=>a.push({k:'c:'+c.id,t:c.t,g:'Campañas'}));return a};
