V.tw=function(){return`<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><p class="mut" style="margin:0;max-width:34em">${x('Cada trabajador puede tener un plan distinto de documentos y campañas. Edita su perfil y su carga.','Each worker can have a different plan of documents and campaigns. Edit their profile and load.')}</p><button onclick="edW()">+ ${x('Agregar trabajador','Add worker')}</button></div><div class="card" style="margin-top:16px">${team.map(m=>`<div class="row"><div style="display:flex;gap:12px;align-items:center;min-width:0">${avatar(m.n,m.img,44)}<div style="min-width:0"><b>${esc(m.n)}</b><br><span class="mut">${esc(tx(m.cargo||'—'))} · ${H[m.a]?P(H[m.a].n):''}</span></div></div><span style="white-space:nowrap"><span class="tag">${asgOf(m).length} ${x('asignados','assigned')}</span> <button onclick="edW('${m.u}')">✎</button> <button class="g" onclick="askDelW('${m.u}')">✕</button></span></div>`).join('')}</div>`};
function ewRead(){if(!WE||!$('#ew1'))return;const m=WE.m;m.n=$('#ew1').value;m.cargo=$('#ew2').value;m.a=$('#ew3').value;m.l=$('#ew4').value}
function edW(u){const m=u?team.find(z=>z.u==u):{n:'',a:'alb',l:'es',cargo:'',img:''};if(!m)return;WE={m:{...m},sel:new Set(m.asg||(u?defAsg(m.a):defAsg('alb')))};ewDraw()}
function ewDraw(){const m=WE.m,sel=WE.sel,cat=catalog();M(`<h3>${m.u?x('Editar trabajador','Edit worker'):x('Nuevo trabajador','New worker')}</h3><div style="display:flex;gap:12px;align-items:center">${avatar(m.n||'?',m.img,56)}<label class="fbtn">📷 ${x('Foto','Photo')}<input type="file" accept="image/*" hidden onchange="ewPhoto(this)"></label></div><label>${x('Nombre','Name')}</label><input id="ew1" value="${esc(m.n)}"><label>${x('Cargo','Job title')}</label>${cargoSel(m.cargo).replace('id="pc" onchange="pcCh(this.value)"','id="ew2" onchange="ewCg(this.value)"')}<label>${x('Área','Area')}</label><select id="ew3">${AO(m.a)}</select><label>${x('Idioma','Language')}</label><select id="ew4">${LG.map(l=>`<option value="${l}" ${l==m.l?'selected':''}>${LN[l]}</option>`).join('')}</select><div style="display:flex;gap:8px;flex-wrap:wrap;margin:14px 0"><button class="g" onclick="ewPlan()">${x('Plan sugerido para su cargo','Suggested plan for the role')}</button><button class="g" onclick="ewAll(1)">${x('Todo','All')}</button><button class="g" onclick="ewAll(0)">${x('Ninguno','None')}</button></div>${GRC.map(g=>{const a=cat.filter(z=>z.g==g);return a.length?`<h4 class="gh">${tx(g)}</h4>${a.map(z=>`<label class="cl"><input type="checkbox" ${sel.has(z.k)?'checked':''} onchange="ewTog('${z.k}',this.checked)">${esc(z._doc||z._tr?z.t:tx(z.t))}</label>`).join('')}`:''}).join('')}<p></p><div style="display:flex;gap:8px"><button onclick="ewSave()">${x('Guardar','Save')}</button><button class="g" onclick="X()">${t('cl')}</button></div>`)}
function ewCg(v){ewRead();WE.m.cargo=v;const a=cargoArea(v);if(a)WE.m.a=a;ewDraw()}
function ewPlan(){ewRead();WE.sel=new Set(defAsg(WE.m.a));ewDraw()}
function ewAll(on){ewRead();WE.sel=new Set(on?defAsg('jef'):[]);ewDraw()}
function ewTog(k,v){const key=/^\d+$/.test(k)?+k:k;if(v)WE.sel.add(key);else WE.sel.delete(key)}
function ewPhoto(inp){const f=inp.files&&inp.files[0];if(!f)return;ewRead();resizeImg(f,d=>{WE.m.img=d;ewDraw()})}
function ewSave(){ewRead();const m=WE.m;if(!m.n.trim())return;m.n=m.n.trim();m.asg=[...WE.sel];if(!m.u){m.u=m.n.toLowerCase().replace(/[^a-z0-9]/g,'')||('t'+Date.now());if(team.some(z=>z.u==m.u))m.u+=Math.floor(10+Math.random()*90);m.k=String(Math.floor(1000+Math.random()*9000));m.p=0}saveTeam(m);if(m.k){const t0=team.find(z=>z.u==m.u);if(t0)t0.k=m.k}X();toast('✓')}
function askDelW(u){const m=team.find(z=>z.u==u);if(!m)return;M(`<h3>${x('¿Quitar a este trabajador?','Remove this worker?')}</h3><p>${esc(m.n)}</p><div style="display:flex;gap:8px"><button style="background:var(--red)" onclick="delW('${u}')">${x('Sí, quitar','Yes, remove')}</button><button class="g" onclick="X()">No</button></div>`)}
function delW(u){const m=team.find(z=>z.u==u);if(!m)return;const o={...m,del:1};delete o.k;TD[u]=o;put('team',u,o);mergeTeam();X()}
function addW(){const n=$('#wn').value.trim();if(!n)return;const u=n.toLowerCase().replace(/[^a-z0-9]/g,'')||('t'+Date.now());saveTeam({n,a:$('#wa').value,l:$('#wl').value,p:0,u:team.some(z=>z.u==u)?u+Math.floor(10+Math.random()*90):u,cargo:''});const m=team[team.length-1];if(m)m.k=String(Math.floor(1000+Math.random()*9000));render()}
