const TODAY=28,TOOLS=[['doc','Documentos','#0C8599'],['eva','Evaluaciones','#7048E8'],['camp','Campañas','#F08C00']],STM=[['done','Completado','#2F9E44'],['prog','En curso','#2B6FD6'],['pend','Pendiente','#B8BEC9'],['late','Atrasado','#E03131']],TC=Object.fromEntries(TOOLS.map(t=>[t[0],t[2]])),PR={},DIL={mjoseph:.32,arojas:.88,lpierre:.55,csilva:.78};
