function syncFromRemoteProg(){const r=PR[ukey()];if(!r)return;if(r.i){for(const id in r.i){const v=r.i[id];prog[id]={d:v[0]||0,t0:v[1]||0,t1:v[2]||0,sc:v[3]??undefined}}}if(r.s)Object.assign(st,r.s);if(r.cd){for(const cid in r.cd)cmp[cid]=r.cd[cid]}if(r.f&&typeof r.f=='object')Object.assign(prof,r.f);if(r.av)MY.img=r.av;if(r.ps)MY.ps=r.ps}
function pushSnap(){if(role!='w'||!user)return;clearTimeout(snapT);const sn=snap();PR[ukey()]=sn;snapT=setTimeout(()=>put('prog',ukey(),sn,1),1200)}
function loadLS(){try{const o=JSON.parse(localStorage.getItem(lsk())||'{}');Object.assign(prog,o.p||{});Object.assign(st,o.s||{});Object.assign(cmp,o.c||{});if(o.f)Object.assign(prof,o.f);}catch(e){}try{MY.img=localStorage.getItem(lsk()+'_av')||'';let ps=+localStorage.getItem(lsk()+'_ps');if(!ps){ps=Date.now();localStorage.setItem(lsk()+'_ps',ps)}MY.ps=ps}catch(e){MY.ps=Date.now()}}
