A.forEach(k=>{if(typeof k=='number'){const o=ID.get(k);if(!o)return;const due=DUE[k]??30;mk(o.tool,'i'+k,o.t,due,real?ri(real.i[k]):0);if(hasQ(k))mk('eva','e'+k,o.t,due+1,real?re(real.i[k]):0)}else if(String(k).startsWith('c:')){const id=k.slice(2),q=CAMP.find(c=>c.id==id);if(q)mk('camp','c'+id,tx(q.t),21,real?{st:real.c&&real.c[id]>=100?'done':real.c&&real.c[id]>0?'prog':'pend'}:0)}});
