const n=all.length,cn=(a,f)=>a.filter(f).length,sc=Object.fromEntries(STM.map(s=>[s[0],cn(all,u=>u.st==s[0])])),pct=Math.round(sc.done/n*100),avgIdx=Math.round(W.reduce((a,w)=>a+w.idx,0)/W.length),op=[...hall,...demoH].filter(h=>(h.s||0)<2).length,demo=false,stN=k=>tx(STM.find(z=>z[0]==k)[1]),tN=k=>tx(TOOLS.find(z=>z[0]==k)[1]);
